#include <stdexcept>
#include <string>
#include <vector>

void replaceAll(std::vector<std::string>& target, const std::vector<std::string>& source)
{
    std::vector<std::string> fresh{};
    for (const std::string& entry : source)
    {
        if (entry.empty())
        {
            throw std::invalid_argument{ "empty entry" };
        }
        fresh.push_back(entry);
    }
    target.swap(fresh);
}

unitTests:
using Names = std::vector<std::string>;
TEST("replaces when everything is valid") { Names t{ "old" }; replaceAll(t, { "a", "b" }); CHECK_EQ(t, (Names{ "a", "b" })); }
TEST("throws on an empty entry") { Names t{ "old" }; CHECK_THROWS_AS(replaceAll(t, { "a", "", "c" }), std::invalid_argument); }
TEST("and leaves the target untouched when it does") { Names t{ "keep", "these" }; try { replaceAll(t, { "a", "b", "" }); } catch (const std::exception&) {} CHECK_EQ(t, (Names{ "keep", "these" })); }
TEST("replacing with nothing") { Names t{ "x" }; replaceAll(t, {}); CHECK(t.empty()); }

